INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-x44-demon-slayer', 1, 'NG Gatling Gun Robotic Weapon Arms (2)', '3D6 S.D.C. single shot; 1D4x10 S.D.C. three-round burst; 2D4x10 S.D.C. (about 1 M.D.) eight-round burst', 0, '2,000 ft (610 m)', 'Each shot or burst counts as one attack. Each arm has two attacks per melee round of its own, four extra for the suit, on top of the pilot''s; the two arms can share a target but never fire linked', '800 rounds per arm (100 long bursts), belt-fed from the drums in the collar; a helmet HUD counts them down', '+2 on initiative and +1 to strike (weapon arms)', 'Anti-monster and assault, secondarily anti-personnel and defense. Two automated arms in the collar, each with two hidden gun cameras, a targeting computer and enemy recognition, so the suit can engage three targets at once (one per arm and the pilot''s own) or mass on one. Small, light silver-coated and wood-tipped rounds trade Mega-Damage for a large payload; owners often load one gun with silver and one with wood, or mix every fourth or fifth round as wood. They fold away behind the suit when idle and are programmed to stay clear of the pilot''s movements.'),
  ('ng-x44-demon-slayer', 2, 'Dual Silver Vibro-Sword', '2D6 M.D. per blade with the Vibro-field on; 4D6 Hit Points/S.D.C. to beings vulnerable to silver, sometimes more', 1, '4 ft (1.2 m) beyond arm''s reach; melee', NULL, NULL, NULL, 'Anti-monster and close combat, secondarily assault and defense. A handheld weapon sold only with this armor: two silver-plated Vibro-Swords joined at the middle into a pole arm with a long blade at each end, for spinning strikes to front, back and sides, or split into one sword per hand, a favorite with Cyber-Knights. Joined, it rides in one hand. The Vibro-field stays off against silver-vulnerable foes, since the silver alone does the work. Some buyers swap it for a TW or other magic melee weapon.'),
  ('ng-x44-demon-slayer', 3, 'Silver Impaler (right forearm)', '2D6 Hit Points/S.D.C. to mortals and beings vulnerable to silver and wood; 4D6 with a hydraulic power punch', 0, 'Arm''s reach; melee', 'Each stab or impalement counts as one melee attack', NULL, NULL, 'Anti-personnel, secondarily defense. A hydraulic wooden spike, silver-coated and 14 inches (36 cm) long, on the right forearm that thrusts out like a power punch without the pilot winding up; it does not fire. Driven into a vampire''s heart it drops the vampire into a coma until the spike is pulled, so a left-in wooden stake keeps one down until it can be destroyed for good. It reaches past the hand and slashes like a retractable blade, but suits only S.D.C. and silver- or wood-vulnerable targets, and wears out (replacement typically 1D4x1000 credits).'),
  ('ng-x44-demon-slayer', 4, 'Stake Launchers (4, right arm)', '2D6 S.D.C. to humans and S.D.C. creatures; double to vampires and other beings vulnerable to wood', 0, '40 ft (12.2 m) maximum, usually fired at 1-8 ft (0.3 to 2.4 m)', 'One at a time; each shot counts as one melee attack', 'Four, with a reload of 12; reloading all four takes one melee round (15 seconds). The chest lockers between shoulders and neck hold six more stakes each, and a stake bandolier carries others', NULL, 'Anti-personnel and assault, secondarily defense. Housings beside the impaler for ordinary wooden stakes, which can be pulled out and used by hand or shot at the undead from close range.'),
  ('ng-x44-demon-slayer', 5, 'Forearm Plasma Blaster (1, left)', '5D6 M.D. per blast', 1, '1,000 ft (305 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-monster and assault, secondarily defense. A low-profile plasma blaster meant less as heavy firepower than as a heat weapon against beings vulnerable to fire. A TW conversion can make it a lightning, fire ball or ice shard discharger.'),
  ('ng-x44-demon-slayer', 6, 'NG-F44 Flamethrower', '4D6 M.D. to the target and to all within 4 ft (1.2 m) of it; 1D6 M.D. on diesel or gasoline', 1, '50 ft (15.2 m)', 'Each fiery blast counts as one melee attack', '10 bursts from a 10 gallon (38 liter) reserve of military napalm, refillable with napalm, diesel or gasoline', NULL, 'Anti-monster and anti-personnel, secondarily assault and defense. A simple hose-and-trigger unit clipped beside the fuel tank on the lower back, usually on the pilot''s dominant (normally right) side, unhooked by reaching back. Valves seal it underwater to keep water out of the napalm. Victims in a bunker, cave or unsealed vehicle without their own air save vs poison or pass out for 1D4 melee rounds.'),
  ('ng-x44-demon-slayer', 7, 'Hand Grenades (8)', 'By grenade type', 1, 'Thrown, about 250 ft (76 m) maximum in this armor', 'One at a time', '8 total, any mix', NULL, 'Anti-personnel, secondarily defense. Stowed two to a compartment in the ribcage boxes along the sides; a common load is two each of plasma, Hex, explosive and smoke. A thrown grenade rolls a D20 to land on target: a large stationary target past 100 ft (30.5 m) needs 10 or better, a small one 16, and 18 past 100 ft; live targets may dodge.'),
  ('ng-xp54-enforcer-guardsman', 1, 'Forearm Laser (1, right)', 'Three settings: 6D6x10 S.D.C. (as printed), 1D6 M.D. or 2D6 M.D.', 1, '1,000 ft (305 m)', 'Each blast counts as one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits; 20 full-power blasts per E-Clip on the battery version', NULL, 'Anti-personnel, secondarily defense. A low-profile, short-range point-and-shoot laser built into the right forearm.'),
  ('ng-xp54-enforcer-guardsman', 2, 'Forearm Grenade Launcher (1, left)', 'By grenade type; police mostly load non-lethal tear gas, stun/flash, Hex or smoke', 1, '500 ft (152 m); a grenade thrown in power armor reaches 200 ft (61 m)', 'Each shot counts as one melee action/attack', '2; more can ride in pouches or a satchel. Reloading both by hand takes 1D4 melee actions', NULL, 'Anti-personnel, secondarily riot control. Tear gas fills a 25 ft (7.6 m) diameter; anyone without a mask or sealed armor is -10 to strike, parry and dodge, -3 on initiative and loses one attack while in it and for 1D6+1 melee rounds after. Stun/flash: for 1D4 melee rounds, -1 on initiative, one attack lost, and -10 to strike, parry and dodge.'),
  ('ng-xf103-firefighter', 1, 'NG-F302 Power Armor M.D.C. Water Cannon', '6D6 Hit Points to vampires; 1D6x10 Hit Points with holy water; none to ordinary people', 0, '300 ft (91.4 m)', 'Single shot only; each blast counts as one melee attack', 'Two tanks: a large 50 gallon (189 liter, 415 lbs/186.7 kg) tank of 250 blasts and a 25 gallon (95 liter, 207.5 lbs/93.3 kg) reserve of 125 blasts, which may hold fire retardant or foam instead; a voice command or three-digit code on the gun picks the tank. A 30 ft (9.1 m) external feed hose (7 kg, 3 M.D.C.) draws from a nearby water source but is too bulky to take into a fight', NULL, 'Firefighting, secondarily anti-vampire. A heavy, flamethrower-like gun of 15 lbs (6.75 kg) fed through an M.D.C. hose from back tanks that strap onto most Combat Cyborgs and ground power armor without changes. NG built it from a pre-Rifts design to spray fire-suppressing chemicals or foam; in Mexico it puts down the undead. The weight and sloshing water cost the user one attack per melee, 10% Spd and -2 on all combat bonuses. In combat it may be swapped for a rail gun, or for drilling and digging gear on rescue jobs.'),
  ('ng-xf103-firefighter', 2, 'Forearm Mini-Laser (1, right)', 'Four settings: 6D6 S.D.C., 2D4x10 S.D.C., 1D4 M.D. or 2D6 M.D.', 1, '1 to 200 ft (0.3 to 61 m)', 'Each blast, at any setting, counts as one melee attack', 'Effectively unlimited; drawn from the power supply', NULL, 'Cutting tool, secondarily combat and defense. A pop-up laser hidden in the right forearm for cutting through locks and walls to get in and out.'),
  ('ng-xf103-firefighter', 3, 'Silver-Plated Knuckle Spikes (optional)', '+1D4 M.D. to punches; 3D6 Hit Points to vampires', 1, 'Melee', NULL, NULL, NULL, 'Three or four silver-plated spikes that can be added over the knuckles.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('ng-x44-demon-slayer', 'ng-xp54-enforcer-guardsman', 'ng-xf103-firefighter');
SELECT 'their 44 locations are in' AS assertion, count(*) AS got, 44 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-x44-demon-slayer', 'ng-xp54-enforcer-guardsman', 'ng-xf103-firefighter');
SELECT 'their 12 weapon entries are in' AS assertion, count(*) AS got, 12 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-x44-demon-slayer', 'ng-xp54-enforcer-guardsman', 'ng-xf103-firefighter');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-x44-demon-slayer', 'ng-xp54-enforcer-guardsman', 'ng-xf103-firefighter') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

